<?php
namespace App\Services;
use App\Domain\Ledger\FinancialCommand; use App\Domain\Ledger\LedgerLine; use App\Models\Beneficiary; use App\Models\BeneficiaryAccount; use App\Models\IdempotencyKey; use App\Models\Transfer; use App\Models\TransferAttempt; use App\Models\TransferQuote; use App\Models\TransferReceipt; use App\Models\User; use App\Models\WalletCurrencyAccount; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class TransferService
{
    public function __construct(private TransferStateService $states, private MockTransferScreeningService $screening, private TransferLimitService $limits, private TransferStepUpService $stepUp, private WalletHoldService $holds, private ChartOfAccountsService $chart) {}
    public function execute(User $user, TransferQuote $quote, string $idempotencyKey, string $challengeId, string $challengeCode, string $scenario='accepted'): Transfer
    {
        if((string)$quote->user_id!==(string)$user->id||$quote->isExpired()||!$quote->sandbox_only) throw ValidationException::withMessages(['quote'=>'The transfer quote is expired, invalid, or not sandbox eligible.']);
        if(!$idempotencyKey) throw ValidationException::withMessages(['idempotency_key'=>'An Idempotency-Key is required.']);
        $payload=['quote_id'=>$quote->id,'challenge_id'=>$challengeId,'source_amount_minor'=>$quote->source_amount_minor,'scenario'=>$scenario];
        $result=app(IdempotencyService::class)->execute('transfer.execute.'.$user->id,$idempotencyKey,$payload,function() use($user,$quote,$idempotencyKey,$challengeId,$challengeCode,$scenario): array {
            return DB::transaction(function() use($user,$quote,$idempotencyKey,$challengeId,$challengeCode,$scenario): array {
                $quote=TransferQuote::with(['beneficiary','sourceAccount.currency'])->whereKey($quote->id)->lockForUpdate()->firstOrFail();
                if($quote->isExpired()) throw ValidationException::withMessages(['quote'=>'The transfer quote has expired.']);
                $this->stepUp->consume($user,$challengeId,$challengeCode);
                $account=$quote->sourceAccount; $beneficiary=$quote->beneficiary; if(!$account||!$beneficiary||!$beneficiary->isOwnedBy($user)) throw ValidationException::withMessages(['transfer'=>'Transfer ownership validation failed.']);
                $this->limits->reserve($user,$quote->source_currency_code,(int)$quote->source_amount_minor+(int)$quote->platform_fee_minor+(int)$quote->provider_fee_minor);
                $transfer=Transfer::create(['transfer_reference'=>'TR-'.strtoupper(Str::random(20)),'user_id'=>$user->id,'source_wallet_currency_account_id'=>$account->id,'beneficiary_id'=>$beneficiary->id,'beneficiary_account_id'=>$quote->beneficiary_account_id,'quote_id'=>$quote->id,'source_currency_code'=>$quote->source_currency_code,'destination_currency_code'=>$quote->destination_currency_code,'source_amount_minor'=>$quote->source_amount_minor,'recipient_amount_minor'=>$quote->recipient_amount_minor,'provider_fee_minor'=>$quote->provider_fee_minor,'platform_fee_minor'=>$quote->platform_fee_minor,'exchange_rate'=>$quote->exchange_rate,'transfer_type'=>$quote->source_currency_code===$quote->destination_currency_code?'internal':'international','status'=>'draft','sandbox_provider_reference'=>null,'sandbox_only'=>true,'metadata'=>['provider_scenario'=>$scenario,'sandbox_only'=>true]]);
                $this->states->transition($transfer,'quoted',$user->id,'quote.accepted'); $this->states->transition($transfer,'awaiting_confirmation',$user->id,'confirmation.started'); $screenings=$this->screening->screen($transfer); $this->states->transition($transfer,'pending_compliance',$user->id,'screening.started');
                if(collect($screenings)->contains(fn($item)=>$item->decision!=='clear')) { $this->states->transition($transfer,'rejected',null,'screening.rejected','Sandbox screening rejected'); return ['transfer_id'=>$transfer->id]; }
                $this->states->transition($transfer,'processing',null,'screening.cleared');
                $holdAmount=(int)$quote->source_amount_minor+(int)$quote->platform_fee_minor+(int)$quote->provider_fee_minor; $hold=$this->holds->create($user,$account,$holdAmount,'transfer:'.$transfer->id,$idempotencyKey.':hold',now()->addMinutes(15)); $transfer->update(['hold_id'=>$hold->id]);
                $provider=app(SandboxTransferProvider::class); $providerResult=$provider->submit($transfer); $transfer->update(['sandbox_provider_reference'=>$providerResult->reference]); TransferAttempt::create(['transfer_id'=>$transfer->id,'attempt_number'=>1,'provider'=>$provider->name(),'status'=>$providerResult->status,'provider_reference'=>$providerResult->reference,'failure_reason'=>$providerResult->failureReason,'started_at'=>now(),'completed_at'=>$providerResult->status==='completed'?now():null,'metadata'=>['sandbox_only'=>true]]);
                if($providerResult->status==='completed') { $counterparty=$this->counterpartyAccount($quote,$beneficiary,$account); $captured=$this->holds->capture($user,$hold,$counterparty->id,$idempotencyKey.':capture'); $transfer->update(['ledger_transaction_id'=>$captured->metadata['capture_transaction_id']??null]); $this->states->transition($transfer,'completed',null,'provider.completed'); $this->receipt($transfer); }
                elseif(in_array($providerResult->status,['failed','timed_out','returned'],true)) { $this->holds->release($user,$hold,$idempotencyKey.':release'); $this->limits->release($user,$quote->source_currency_code,$holdAmount); $this->states->transition($transfer,$providerResult->status==='returned'?'returned':($providerResult->status==='timed_out'?'failed':'failed'),null,'provider.'.$providerResult->status,$providerResult->failureReason); }
                return ['transfer_id'=>$transfer->id];
            });
        });
        return Transfer::with(['beneficiary','events','screenings','attempts','receipt'])->findOrFail($result->value['transfer_id']);
    }
    public function cancel(User $user, Transfer $transfer): Transfer { if((string)$transfer->user_id!==(string)$user->id) throw ValidationException::withMessages(['transfer'=>'Transfer access denied.']); return DB::transaction(function() use($user,$transfer): Transfer { $transfer=Transfer::whereKey($transfer->id)->lockForUpdate()->firstOrFail(); if($transfer->hold_id) { $hold=$transfer->hold()->first(); if($hold&&$hold->status==='active') $this->holds->release($user,$hold,'cancel:'.$transfer->id); } $this->limits->release($user,$transfer->source_currency_code,(int)$transfer->source_amount_minor+(int)$transfer->platform_fee_minor); return $this->states->transition($transfer,'cancelled',$user->id,'user.cancelled'); }); }
    private function counterpartyAccount(TransferQuote $quote, Beneficiary $beneficiary, WalletCurrencyAccount $source): \App\Models\LedgerAccount { $account=$beneficiary->accounts()->whereKey($quote->beneficiary_account_id)->firstOrFail(); if($account->account_type==='internal_wallet') { $details=json_decode(Crypt::decryptString($account->account_details_encrypted),true,flags:JSON_THROW_ON_ERROR); $target=WalletCurrencyAccount::with('wallet')->find($details['wallet_account_id']??null); if(!$target||$target->status!=='active'||$target->currency()->value('code')!==$source->currency()->value('code')) throw ValidationException::withMessages(['beneficiary'=>'Internal wallet beneficiary is invalid.']); return $target->ledgerAccount()->firstOrFail(); } return $this->chart->provisionSystemAccount('system.transfer.settlement.'.strtolower($source->currency->code),'Sandbox transfer settlement '.$source->currency->code,'asset','debit',$source->currency->code,true); }
    private function receipt(Transfer $transfer): void { $snapshot=['transfer_reference'=>$transfer->transfer_reference,'source_currency_code'=>$transfer->source_currency_code,'destination_currency_code'=>$transfer->destination_currency_code,'source_amount_minor'=>$transfer->source_amount_minor,'recipient_amount_minor'=>$transfer->recipient_amount_minor,'status'=>'completed','sandbox_only'=>true]; TransferReceipt::create(['transfer_id'=>$transfer->id,'receipt_reference'=>'REC-'.strtoupper(Str::random(20)),'receipt_hash'=>hash('sha256',json_encode($snapshot,JSON_THROW_ON_ERROR)),'snapshot'=>$snapshot,'issued_at'=>now()]); }
}
